// GitHub Pages compatibility shim. When window.PAGES_MODE is true (set by
// pages-config.js in the Pages build only), this intercepts every fetch()
// call app.js/landing.js already make to the FastAPI API and answers them
// from the static JSON generated by scripts/build_pages.py instead - so
// app.js and landing.js run completely unmodified in both deployment modes.
// See docs/GITHUB_PAGES.md for the full architecture.
(() => {
  'use strict';
  if (!window.PAGES_MODE) return;

  // Pages mode publishes the dashboard as public content (see docs/GITHUB_PAGES.md
  // - client-side auth cannot make a bundled static JSON file private, so
  // gating it behind a fake "sign in" would be exactly the dishonest pattern
  // this project explicitly rejects). The nav's sign-in slot becomes a
  // direct link to that public dashboard instead of a login prompt.
  const authLink = document.getElementById('navAuthLink');
  if (authLink) { authLink.textContent = 'Live dashboard'; authLink.href = '/dashboard/'; }

  const DATA = '/data/';

  // Dashboard's "Listed" filter is this build's rolling-5-year historical
  // view (see docs/GITHUB_PAGES.md) - surface the actual computed window
  // next to the results count so it never reads as an unlabeled, arbitrary
  // cutoff. Purely additive DOM patch; app.js/app.html are untouched.
  function initHistoryWindowNote() {
    const statusSelect = document.getElementById('status');
    const countPill = document.getElementById('countPill');
    if (!statusSelect || !countPill) return;
    const note = document.createElement('span');
    note.id = 'historyWindowNote';
    note.className = 'pill';
    note.style.display = 'none';
    countPill.insertAdjacentElement('afterend', note);
    fetch(DATA + 'manifest.json').then(r => r.json()).then(m => {
      const fmt = d => new Date(d).toLocaleDateString('en-US', { month: 'short', year: 'numeric' });
      note.textContent = `Past 5 Years · ${fmt(m.history_window_start)} – ${fmt(m.history_window_end)}`;
      const sync = () => { note.style.display = statusSelect.value === 'Listed' ? '' : 'none'; };
      statusSelect.addEventListener('change', sync);
      sync();
    }).catch(() => {});
  }
  if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', initHistoryWindowNote);
  else initHistoryWindowNote();
  // navigator.sendBeacon() and EventSource are separate browser APIs -
  // neither goes through window.fetch, so the override below never sees
  // landing.js's analytics beacon or app.js's live-monitor stream. Both
  // target /api/events, which has no server to answer on Pages. Patched
  // here so they fail the same way they already gracefully degrade (the
  // beacon is fire-and-forget; EventSource already falls back to polling
  // via its own onerror handler) without a real failed network request.
  if (navigator.sendBeacon) {
    const realSendBeacon = navigator.sendBeacon.bind(navigator);
    navigator.sendBeacon = (url, data) => {
      try { if (new URL(url, location.origin).pathname === '/api/events') return true; } catch (e) {}
      return realSendBeacon(url, data);
    };
  }
  const RealEventSource = window.EventSource;
  window.EventSource = function (url, opts) {
    try {
      if (new URL(url, location.origin).pathname === '/api/events') {
        const stub = new EventTarget();
        stub.readyState = 2; // CLOSED
        stub.close = () => {};
        setTimeout(() => {
          const ev = new Event('error');
          stub.dispatchEvent(ev);
          if (typeof stub.onerror === 'function') stub.onerror(ev);
        }, 0);
        return stub;
      }
    } catch (e) {}
    return new RealEventSource(url, opts);
  };

  const realFetch = window.fetch.bind(window);
  const cache = {};

  async function getJSON(path) {
    if (cache[path]) return cache[path];
    const r = await realFetch(path);
    if (!r.ok) throw new Error('missing static data file: ' + path);
    const j = await r.json();
    cache[path] = j;
    return j;
  }

  const loadUpcoming = async () => {
    const [india, us] = await Promise.all([getJSON(DATA + 'upcoming/india.json'), getJSON(DATA + 'upcoming/us.json')]);
    return india.concat(us);
  };
  const loadHistory = async () => {
    const [india, us] = await Promise.all([getJSON(DATA + 'history/india-5y.json'), getJSON(DATA + 'history/us-5y.json')]);
    return india.concat(us);
  };

  function filterRows(rows, country, q, limit) {
    let out = rows;
    if (country && country !== 'all') out = out.filter(x => x.country === country);
    if (q) { const needle = q.toLowerCase(); out = out.filter(x => (x.company || '').toLowerCase().includes(needle) || (x.symbol || '').toLowerCase().includes(needle)); }
    return out.slice(0, limit || 300);
  }

  const json = (obj, status) => new Response(JSON.stringify(obj), { status: status || 200, headers: { 'Content-Type': 'application/json' } });

  async function handleWaitlist(init) {
    const endpoint = window.PUBLIC_WAITLIST_ENDPOINT;
    if (!endpoint) {
      // Honest configuration state, never a fake success message (see
      // spec: "DO NOT show a fake success message" if the endpoint is unset).
      return json({ detail: "Early access isn't wired up in this preview build yet - the Google Apps Script endpoint hasn't been deployed. See docs/GITHUB_PAGES.md." }, 501);
    }
    try {
      const r = await realFetch(endpoint, { method: 'POST', body: init && init.body, headers: { 'Content-Type': 'text/plain;charset=utf-8' } });
      const j = await r.json().catch(() => ({}));
      if (!r.ok || j.ok === false) return json({ detail: j.detail || j.error || 'Signup failed.' }, r.status || 502);
      return json({ ok: true, message: j.message || "You're on the early-access list.", referral_code: j.referral_code || '' });
    } catch (e) {
      return json({ detail: 'Could not reach the signup service. Please try again.' }, 502);
    }
  }

  window.fetch = async function (input, init) {
    const url = typeof input === 'string' ? input : input.url;
    let u;
    try { u = new URL(url, location.origin); } catch (e) { return realFetch(input, init); }
    const path = u.pathname, params = u.searchParams;
    const method = ((init && init.method) || 'GET').toUpperCase();

    try {
      if (path === '/api/auth/me') return json({ authenticated: false });
      if (path === '/api/clerk/config') return json({ publishable_key: '', configured: false });
      if (path === '/api/events' && method === 'POST') return json({ ok: true }); // analytics: no server in static mode, swallow
      if (path === '/api/public/highlights') return json(await getJSON(DATA + 'highlights.json'));
      if (path === '/api/waitlist' && method === 'POST') return handleWaitlist(init);
      if (path === '/api/summary') { const m = await getJSON(DATA + 'manifest.json'); return json(m.summary); }

      if (path === '/api/ipos' && method === 'GET') {
        const country = params.get('country') || 'all';
        const status = params.get('status') || 'all';
        const q = params.get('q') || '';
        const limit = parseInt(params.get('limit') || '300', 10);
        // Deliberate Pages-mode default: an unfiltered load ("All stages")
        // shows the upcoming/current universe, not five years of history -
        // the dashboard's own "Listed" filter is how a visitor reaches the
        // historical set. This differs from server mode's literal "all IPOs
        // ever" default on purpose (see docs/GITHUB_PAGES.md).
        let rows;
        if (status === 'Listed') rows = await loadHistory();
        else if (status === 'all') rows = await loadUpcoming();
        else rows = (await loadUpcoming()).filter(x => x.status === status);
        return json(filterRows(rows, country, q, limit));
      }
      const ipoMatch = path.match(/^\/api\/ipos\/(\d+)(\/(valuation|similar|changes))?$/);
      if (ipoMatch && method === 'GET') {
        const full = await getJSON(DATA + 'ipo/' + ipoMatch[1] + '.json');
        const sub = ipoMatch[3];
        if (!sub) return json(full.detail);
        return json(full[sub]);
      }
      // First-party analytics beacon (app/main.py's /api/events) logs
      // server-side - there is no server on Pages to log to. Answering
      // honestly with {ok:false} (the same shape the real endpoint returns
      // for a rejected event) rather than letting it fall through to the
      // static host and surface as a console error.
      if (path === '/api/events') return json({ ok: false });
      if (path === '/api/performance') return json(await loadHistory());
      if (path === '/api/source-health') return json(await getJSON(DATA + 'source-health.json'));
      if (path === '/api/backtest') return json(await getJSON(DATA + 'backtest.json'));
      if (path === '/api/track-record') return json(await getJSON(DATA + 'track-record.json'));
      if (path === '/api/model-performance') return json(await getJSON(DATA + 'model-performance.json'));
    } catch (e) {
      return json({ detail: 'Static data unavailable: ' + e.message }, 503);
    }
    return realFetch(input, init); // e.g. /static/* assets - real network fetch
  };
})();
